vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(2.63, 0.41, 0.55);
    return a + b * cos(6.28318 * (c * t + d));
}

// Rotation matrix for rotation around the Y-axis
mat3 rotationY(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat3(
        c, 0.0, -s,
        0.0, 1.0,  0.0,
        s, 0.0,  c
    );
}

// Function to define the cube's signed distance field
float cubeSDF(vec3 p, vec3 b) {
    vec3 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}

// Raymarching function
float raymarch(vec3 ro, vec3 rd, out vec3 hitPos) {
    float t = 0.0;
    for (int i = 0; i < 100; i++) {
        vec3 p = ro + t * rd;

        // Apply rotation to the cube
        p = rotationY(iTime) * p;

        float d = cubeSDF(p, vec3(0.5)); // Cube size
        if (d < 0.001) {
            hitPos = p;
            return t;
        }
        t += d;
        if (t > 50.0) break; // Avoid infinite loop
    }
    return -1.0; // No hit
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize pixel coordinates
    vec2 uv = (fragCoord.xy / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Camera setup
    vec3 ro = vec3(0.0, 0.0, 2.0); // Ray origin
    vec3 rd = normalize(vec3(uv, -1.5)); // Ray direction

    // Raymarching
    vec3 hitPos;
    float t = raymarch(ro, rd, hitPos);
    if (t > 0.0) {
        float colFactor = length(hitPos);
        vec3 col = palette(colFactor + iTime * 0.1);
        fragColor = vec4(col, 1.0);
    } else {
        fragColor = vec4(0.0); // Background color
    }
}
